<script src="https://cdnjs.cloudflare.com/ajax/libs/flowbite/2.5.2/flowbite.min.js"></script><script>const root=document.documentElement;const themeToggle=document.querySelector('[data-theme-toggle]');const savedTheme=localStorage.getItem('iris-theme');const initialDark=savedTheme?savedTheme==='dark':window.matchMedia('(prefers-color-scheme: dark)').matches;root.classList.toggle('dark',initialDark);document.body.classList.toggle('dark',initialDark);themeToggle.setAttribute('aria-pressed',initialDark?'true':'false');themeToggle.addEventListener('click',()=>{const dark=root.classList.toggle('dark');document.body.classList.toggle('dark',dark);themeToggle.setAttribute('aria-pressed',dark?'true':'false');localStorage.setItem('iris-theme',dark?'dark':'light');});</script>
